  match PML.ps_win ps with None => p' = 0 /\ win' = None | Some (p, e) => p' <= e /\ win' = Some (p', e) end ->
  PMLA.parser_at segs IC M' P (PML.PS (PML.ps_st ps) (PML.ps_sst ps) (PML.ps_nst ps) more' (PML.ps_done ps) (PML.ps_level ps) (PML.ps_stack ps) (PML.ps_sb ps) (PML.ps_scap ps)
                             (PML.ps_bcap ps) (PML.ps_bptr ps) (PML.ps_buf ps) win').
